SELECT op.seq, member.position, member.transfer_id, EXISTS(SELECT 1 FROM sync_upload_batch AS batch WHERE batch.batch_id = op.batch_id AND batch.op_id = op.seq), EXISTS(SELECT 1 FROM sync_upload AS upload WHERE upload.transfer_id = member.transfer_id AND upload.batch = op.batch_id), upload.cycle_id, upload.row_id FROM op JOIN op_transfer AS member ON member.op_id = op.seq LEFT JOIN sync_upload AS upload ON upload.transfer_id = member.transfer_id WHERE op.intent_state = 'ready' AND op.origin_kind = 'transfer_group' ORDER BY op.seq, member.position
